const a = $input.all()[0].json;
const startDate = new Date(a.startTime || a.start || a.scheduledAt);
const fmt = (d) => d.toLocaleString('en-IN', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit', timeZone: 'Asia/Kolkata' });
const meetingLink = a.meetingLink || a.location || (a.type === 'ONLINE' ? 'https://meet.dayjoy.in/' + a.id : '');
const locationLine = a.type === 'ONLINE'
  ? `<p><strong>Join Online:</strong> <a href="${meetingLink}">${meetingLink}</a></p>`
  : `<p><strong>Location:</strong> ${a.location || 'To be confirmed'}</p>`;
const html = `
<!doctype html><html><body style="font-family:Arial,Helvetica,sans-serif;color:#1f2937;background:#fff7ed;margin:0;padding:0;">
  <div style="max-width:560px;margin:0 auto;padding:32px;">
    <h1 style="color:#ea580c;">⏰ Appointment Reminder</h1>
    <p>Hi ${a.customerName || 'Customer'},</p>
    <p>This is a friendly reminder for your upcoming Dayjoy appointment.</p>
    <table style="width:100%;border-collapse:collapse;margin:16px 0;">
      <tr><td style="padding:8px;background:#ffedd5;"><strong>When:</strong></td><td style="padding:8px;background:#fff;">${fmt(startDate)}</td></tr>
      <tr><td style="padding:8px;background:#ffedd5;"><strong>With:</strong></td><td style="padding:8px;background:#fff;">${a.employeeName || a.assigneeName || 'Dayjoy Team'}</td></tr>
      <tr><td style="padding:8px;background:#ffedd5;"><strong>Agenda:</strong></td><td style="padding:8px;background:#fff;">${a.title || a.agenda || 'Consultation'}</td></tr>
    </table>
    ${locationLine}
    <p style="margin-top:16px;"><a href="https://app.dayjoy.in/appointments/${a.id}" style="background:#ea580c;color:#fff;padding:10px 18px;border-radius:6px;text-decoration:none;display:inline-block;">Manage Appointment →</a></p>
    <hr style="margin:24px 0;border:none;border-top:1px solid #fed7aa;" />
    <p style="font-size:12px;color:#6b7280;">Dayjoy Wellness Pvt. Ltd. · support@dayjoy.in</p>
  </div>
</body></html>`;
return [{
  json: {
    html,
    subject: `Reminder: Appointment on ${fmt(startDate)}`,
    customerEmail: a.customerEmail,
    employeeEmail: a.employeeEmail,
    appointmentId: a.id,
    tenantId: a.tenantId
  }
}];
